values.content:
=You are a senior real estate copywriter producing 5 platform-specific variants for the same listing.

LISTING:
Address: {{ $json.fields.address }}
Price: ${{ $json.fields.price }}
Beds: {{ $json.fields.beds }}
Baths: {{ $json.fields.baths }}
SqFt: {{ $json.fields.sqft }}
Key features: {{ $json.fields.features }}
Neighborhood: {{ $json.fields.neighborhood }}
Agent: {{ $json.fields.agent_name }}

Return ONLY valid JSON:
{
  "mls_description": "160-220 word formal description, MLS-compliant, no all-caps, no exclamations",
  "instagram_caption": "90-130 word IG caption, conversational, 1 line breaks, 4-6 relevant hashtags",
  "instagram_slides": ["slide 1 headline", "slide 2 feature", "slide 3 feature", "slide 4 neighborhood", "slide 5 CTA"],
  "facebook_marketplace": "60-90 word FB Marketplace listing, casual, ends with 'DM to schedule a viewing'",
  "zillow_blurb": "exactly 1 sentence, max 140 chars, hook-first",
  "landing_page": {
    "hero_headline": "6-10 words, benefit-first",
    "hero_sub": "15-25 word supporting line",
    "three_features": ["feature 1 with number", "feature 2 with number", "feature 3 with number"],
    "cta": "Book a viewing — 7 words max"
  }
}

parameters.jsCode:
const raw = $input.first().json.content?.[0]?.text || $input.first().json.text || '';
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('No JSON in Claude reply');
const v = JSON.parse(match[0]);
const row = $('New listing in Airtable').first().json;
return [{
  json: {
    ...v,
    listing_id: row.id,
    address: row.fields.address,
    price: row.fields.price,
    slug: row.fields.address.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    photo_urls: (row.fields.photos || []).map(p => p.url)
  }
}];

